<script>
import { getAgentperformance } from '@/api/user'
export default {
  data() {
    return {
      showFilter: false,
      currentIndex: 1,
      allData: {
        num1: 0,
        num2: 0,
        num3: 0
      },
      dataList: [
      ]
    }
  },
  created() {
    this.getData()
  },
  methods: {
    getData() {
      getAgentperformance({ type: this.currentIndex === 1 ? '1' : '2' }).then(res => {
        this.dataList = res.datalist.map(item => {
          return {
            type: item.gametypename,
            num: item.allmons,
            num1: item.downbuys,
            num2: item.performpor,
            gametype: item.gametype
          }
        })
      })
    },
    goDetail(path, queryType) {
      this.$router.push({ path, query: { gametype: queryType, type: this.currentIndex === 1 ? '1' : '2' }})
    }
  }
}
