        this.info2 = res
      })
    },
    goCommisRecord(path, type) {
      this.$router.push({ path: path, query: { type: type }})
    },
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('czym.czym09'))
        },
        (e) => {
